/// (1) index walk bounded by a slice length: `i += 1` cannot overflow.
pub fn count_args(args: &[String]) -> usize {
    let mut i = 0;
    while i < args.len() {
        i += 1;
    }
    i
}

/// (2) Box::new never yields null (allocation failure aborts).
pub fn boxed(x: u64) -> Box<u64> {
    Box::new(x)
}

/// (3) guarded decrement: `d -= 1` only when `d > 0`.
pub fn dec_first_nonzero(digits: &mut [u8]) {
    let mut i = 0;
    while i < digits.len() {
        if digits[i] > 0 {
            digits[i] -= 1;
            break;
        }
        digits[i] = 9;
        i += 1;
    }
}
